                <XAxis type="number" tick={{ fill: "#64748b", fontSize: 12 }} unit=" t" />
                <YAxis
                  type="category"
                  dataKey="label"
                  width={110}
                  tick={{ fill: "#334155", fontSize: 12 }}
                />
                <Tooltip
                  formatter={(v, _n, ctx) => [
                    `${Number(v).toLocaleString()} t (${(ctx as { payload?: { year?: number } }).payload?.year ?? ""})`,
                    "Active ingredient",
                  ]}
                  labelFormatter={(_, payload) =>
                    (payload as { payload?: { basis?: string } }[])?.[0]?.payload
                      ?.basis ?? ""
                  }
                />
                <Bar dataKey="tonnes" name="Tonnes" radius={[0, 4, 4, 0]}>
                  {tonnageData.map((row) => (
                    <Cell
                      key={row.id}
                      fill={
                        row.confidence === "estimated" && highlightEstimated
                          ? COLORS.estimated
                          : row.id === "china"
                            ? COLORS.china
                            : row.id === "united_states"
                              ? COLORS.us
                              : row.id === "eu27"
                                ? COLORS.eu
                                : COLORS.animal
                      }
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "intensity" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="Same story, different rulers"
            subtitle="mg/kg and mg/PCU on one axis; DDD lives on another planet ??? shown in the table below."
          >
            <div className="h-[320px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart
                  data={intensityMgKg}
                  layout="vertical"
                  margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
