                    ]}
                    type="monotone"
                    dataKey="mgPcu"
                    name="F2F 2030 path"
                    stroke={COLORS.muted}
                    strokeDasharray="6 4"
                    dot={false}
                  />
                ) : null}
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "species" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
