                  domain={[2015, 2024]}
                  ticks={[2015, 2017, 2019, 2021, 2023]}
                  tick={{ fill: "#64748b", fontSize: 12 }}
                  allowDuplicatedCategory={false}
                />
                <YAxis
                  yAxisId="eu"
                  tick={{ fill: COLORS.eu, fontSize: 11 }}
                  label={{
                    value: "EU mg/PCU",
                    angle: -90,
                    position: "insideLeft",
                    fill: COLORS.eu,
                    fontSize: 11,
                  }}
                  hide={trendFocus === "us-sales"}
                />
                <YAxis
                  yAxisId="us"
                  orientation="right"
                  tick={{ fill: COLORS.us, fontSize: 11 }}
                  label={{
                    value: "US tonnes",
                    angle: 90,
                    position: "insideRight",
                    fill: COLORS.us,
                    fontSize: 11,
                  }}
                  hide={trendFocus === "eu-pcu"}
                />
                <Tooltip />
                <Legend />
                {trendFocus !== "us-sales" ? (
                  <Line
                    yAxisId="eu"
                    data={EU_PCU_TREND}
                    type="monotone"
                    dataKey="mgPcu"
                    name="EU mg/PCU"
                    stroke={COLORS.eu}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                ) : null}
                {trendFocus !== "eu-pcu" ? (
                  <Line
                    yAxisId="us"
                    data={US_SALES_TREND}
                    type="monotone"
                    dataKey="medicallyImportantTonnes"
                    name="US MI tonnes"
                    stroke={COLORS.us}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                ) : null}
                {trendFocus !== "us-sales" ? (
                  <Line
                    yAxisId="eu"
                    data={[
                      { year: 2018, mgPcu: HEADLINE.eu2018RefMgPcu },
                      { year: 2030, mgPcu: HEADLINE.eu2030TargetMgPcu },
                    ]}
                    type="monotone"
                    dataKey="mgPcu"
                    name="F2F 2030 path"
                    stroke={COLORS.muted}
                    strokeDasharray="6 4"
                    dot={false}
                  />
                ) : null}
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "species" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="US medically important sales by species (2023)"
            subtitle="FDA CVM species attribution ??? swine and cattle dominate mass."
          >
            <div className="h-[300px] w-full min-w-0">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie
                    data={US_SPECIES_SHARE}
                    dataKey="sharePct"
                    nameKey="species"
                    cx="50%"
                    cy="50%"
                    innerRadius={55}
                    outerRadius={95}
                    paddingAngle={2}
