      ) : null}

      {panel === "eu-scatter" ? (
        <div className="grid gap-4 lg:grid-cols-2">
          <ChartCard
            title="EU countries: animal mg/kg vs human DDD"
            subtitle="Bubble size ??? veterinary tonnes (ESUAvet 2023). Axes deliberately use different units."
          >
