                  />
                  <ZAxis type="number" dataKey="animalTonnes" range={[60, 400]} />
                  <Tooltip
                    cursor={{ strokeDasharray: "3 3" }}
                    formatter={(v, name) => {
                      const n = String(name);
                      if (n === "Animal mg/kg") return [`${v} mg/kg`, n];
                      if (n === "Human DDD") return [`${v} DDD`, n];
