                    dataKey="mgPcu"
                    name="EU mg/PCU"
                    stroke={COLORS.eu}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                ) : null}
                {trendFocus !== "eu-pcu" ? (
                  <Line
                    yAxisId="us"
                    data={US_SALES_TREND}
                    type="monotone"
                    dataKey="medicallyImportantTonnes"
                    name="US MI tonnes"
                    stroke={COLORS.us}
                    strokeWidth={2.5}
                    dot={{ r: 3 }}
                  />
                ) : null}
