                      <Cell key={row.id} fill={COLORS.animal} />
                    ))}
                  </Scatter>
                </ScatterChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard
            title="Radar: animal intensity vs scaled human DDD"
            subtitle="Human DDD ??4 so both series share a readable radar radius ??? illustrative only."
          >
