              <ControlChip key={id} active={trendFocus === id} onClick={() => setTrendFocus(id)}>
                {label}
              </ControlChip>
            ))}
          </div>
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart margin={{ top: 8, right: 16, left: 8, bottom: 8 }}>
