                      <Cell
                        key={row.id}
                        fill={row.sector === "human" ? COLORS.human : COLORS.animal}
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
          <ChartCard title="What each metric actually measures" subtitle="Read before ranking countries.">
            <ul className="space-y-3 text-sm text-slate-700">
