                  <p className="font-semibold text-slate-900">
                    {m.metric}{" "}
                    <span className="font-normal text-slate-500">?? {m.sector}</span>
                  </p>
                  <p className="mt-1">
                    <span className="text-slate-500">Counts:</span> {m.whatItCounts}
