                  tick={{ fill: "#334155", fontSize: 12 }}
                />
                <Tooltip />
                <Bar dataKey="tonnes" name="Tonnes" radius={[0, 4, 4, 0]}>
                  {tonnageData.map((row) => (
                    <Cell
                      key={row.id}
                      fill={
                        row.confidence === "estimated" && highlightEstimated
                          ? COLORS.estimated
                          : row.id === "china"
                            ? COLORS.china
                            : row.id === "united_states"
                              ? COLORS.us
                              : row.id === "eu27"
                                ? COLORS.eu
                                : COLORS.animal
                      }
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      ) : null}

      {panel === "intensity" ? (
        <div className="grid gap-4 lg:grid-cols-2">
